#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long long num = strtoll(argv[1], &end1, 10);
    long long den = strtoll(argv[2], &end2, 10);
    // check for parsing errors (non‑numeric characters)
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // denominator zero -> error
    if (den == 0) {
        puts("[ERROR]");
        return 0;
    }
    // limit on absolute numerator (as observed in the original binary)
    if (llabs(num) > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Compute continued fraction terms using the Euclidean algorithm
    long long a[100000]; // enough for any reasonable input
    int cnt = 0;
    while (den != 0) {
        long long q = num / den;               // integer division truncates toward 0
        a[cnt++] = q;
        long long r = num - q * den;           // remainder
        num = den;
        den = r;
    }
    // Output in the form [a0; a1, a2, ...]
    putchar('[');
    if (cnt > 0) {
        printf("%lld", a[0]);
        if (cnt > 1) {
            putchar(';');
            putchar(' ');
            printf("%lld", a[1]);
            for (int i = 2; i < cnt; ++i) {
                printf(", %lld", a[i]);
            }
        }
    }
    putchar(']');
    putchar('\n');
    return 0;
}
